@Service
public class UserService {
    private final UserRepository repository;

    public UserService(
            UserRepository repository
    ) {
        this.repository = repository;
    }

    @Transactional
    public void changeEmail(
        Long userId,
        String email
    ) {
        User user = repository
            .findById(userId)
            .orElseThrow();

        user.setEmail(email);
    }
}

public record UserResponse(
    Long id,
    String name,
    String email
) {}
